-- Milestone 4: make the database queue the single playback authority.
ALTER TABLE public.tracks ALTER COLUMN scene_id DROP NOT NULL;
ALTER TABLE public.tracks ADD COLUMN catalogue_key text;
UPDATE public.tracks SET catalogue_key = 'legacy:' || id::text WHERE catalogue_key IS NULL;
ALTER TABLE public.tracks ALTER COLUMN catalogue_key SET NOT NULL;
CREATE UNIQUE INDEX tracks_catalogue_key_key ON public.tracks(catalogue_key);

CREATE TABLE public.curated_sets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scene_id uuid NOT NULL REFERENCES public.scenes(id) ON DELETE CASCADE,
  title text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  shuffle_start boolean NOT NULL DEFAULT true,
  origin_provider text,
  origin_external_id text,
  imported_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX curated_sets_one_active_per_scene ON public.curated_sets(scene_id) WHERE is_active;
CREATE INDEX curated_sets_scene_order_idx ON public.curated_sets(scene_id, sort_order);

CREATE TABLE public.curated_set_tracks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  curated_set_id uuid NOT NULL REFERENCES public.curated_sets(id) ON DELETE CASCADE,
  track_id uuid NOT NULL REFERENCES public.tracks(id) ON DELETE RESTRICT,
  position integer NOT NULL CHECK (position > 0),
  daypart_tag text NOT NULL DEFAULT 'all',
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(curated_set_id, position)
);
CREATE INDEX curated_set_tracks_track_idx ON public.curated_set_tracks(track_id);

CREATE TABLE public.playback_sources (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  track_id uuid NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('youtube')),
  provider_item_id text NOT NULL,
  source_url text NOT NULL,
  provider_title text,
  provider_channel text,
  priority integer NOT NULL DEFAULT 0,
  validated_at timestamptz NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(provider, provider_item_id)
);
CREATE INDEX playback_sources_track_priority_idx ON public.playback_sources(track_id, is_active, priority);

CREATE TABLE public.playback_source_failures (
  source_id uuid NOT NULL REFERENCES public.playback_sources(id) ON DELETE CASCADE,
  error_code integer NOT NULL CHECK (error_code IN (2, 5, 100, 101, 150, 153)),
  failed_on date NOT NULL DEFAULT current_date,
  occurrence_count bigint NOT NULL DEFAULT 1 CHECK (occurrence_count > 0),
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(source_id, error_code, failed_on)
);

ALTER TABLE public.curated_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curated_set_tracks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.playback_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.playback_source_failures ENABLE ROW LEVEL SECURITY;

CREATE POLICY "active sets public read" ON public.curated_sets FOR SELECT TO anon, authenticated
USING (is_active AND EXISTS (SELECT 1 FROM public.scenes s WHERE s.id = curated_sets.scene_id AND s.is_live));
CREATE POLICY "active set tracks public read" ON public.curated_set_tracks FOR SELECT TO anon, authenticated
USING (EXISTS (
  SELECT 1 FROM public.curated_sets cs JOIN public.scenes s ON s.id = cs.scene_id
  WHERE cs.id = curated_set_tracks.curated_set_id AND cs.is_active AND s.is_live
));
CREATE POLICY "active playback sources public read" ON public.playback_sources FOR SELECT TO anon, authenticated
USING (is_active AND EXISTS (
  SELECT 1 FROM public.curated_set_tracks cst
  JOIN public.curated_sets cs ON cs.id = cst.curated_set_id
  JOIN public.scenes s ON s.id = cs.scene_id
  WHERE cst.track_id = playback_sources.track_id AND cs.is_active AND s.is_live
));

REVOKE ALL ON public.curated_sets, public.curated_set_tracks, public.playback_sources, public.playback_source_failures FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.curated_sets, public.curated_set_tracks, public.playback_sources TO anon, authenticated;
GRANT ALL ON public.curated_sets, public.curated_set_tracks, public.playback_sources, public.playback_source_failures TO service_role;

CREATE OR REPLACE FUNCTION public.record_playback_source_failure(p_source_id uuid, p_error_code integer)
RETURNS void
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF p_error_code NOT IN (2, 5, 100, 101, 150, 153) THEN
    RAISE EXCEPTION 'unsupported YouTube error code';
  END IF;
  INSERT INTO public.playback_source_failures(source_id, error_code)
  VALUES (p_source_id, p_error_code)
  ON CONFLICT (source_id, error_code, failed_on) DO UPDATE
  SET occurrence_count = public.playback_source_failures.occurrence_count + 1,
      last_seen_at = now();
END;
$$;
REVOKE ALL ON FUNCTION public.record_playback_source_failure(uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_playback_source_failure(uuid, integer) TO service_role;

